info.description:
Importable Postman collection for the Hot Chocolate API at http://localhost:5100/graphql.

Before running:
1. Start the API:  dotnet run --project src\GraphQLPractice.Api
2. Start Postgres:  docker compose up -d  (in _infra\postgres-master-test)

Collection variables 'postId', 'authorId' and 'tagId' hold sample Relay global IDs (base64 of 'Type:localId'). Run 'Global object identification > Get IDs' to fetch current ones and paste them in, or just use the defaults against a freshly seeded database.

Subscriptions need the WebSocket folder (Postman 'WebSocket' request), not the HTTP folders.

Chaining: several requests have test scripts that capture returned global ids into collection variables, so you can run them in order without copy/paste:
  Get IDs  ->  sets {{postId}}, {{authorId}}, {{tagId}}
  Create post          ->  sets {{postId}}
  Create author        ->  sets {{authorId}}
  Create tag           ->  sets {{tagId}}
  Add comment          ->  sets {{commentId}}
Update post / Delete post / Add comment / Delete tag read those variables (a pre-request check fails fast if an id is missing). If Postman replaces {{postId}} with a literal instead of a value, run Get IDs (or Create post) once first.

graphql.query:
{
  __schema {
    queryType {
      fields {
        name
        args { name type { kind name ofType { kind name } } }
      }
    }
  }
}

{
  __type(name: "Node") {
    name
    kind
    possibleTypes { name }
  }
}

{
  __type(name: "Query") {
    fields { name isDeprecated deprecationReason }
  }
}

query GetPosts($first: Int) {
  posts(first: $first) {
    totalCount
    pageInfo { hasNextPage endCursor }
    nodes { id title slug status }
  }
}

query NextPage($first: Int, $after: String) {
  posts(first: $first, after: $after) {
    pageInfo { hasNextPage endCursor }
    nodes { id title }
  }
}

query LastPosts($last: Int) {
  posts(last: $last) {
    pageInfo { hasPreviousPage startCursor }
    nodes { id title }
  }
}

query ByStatus($where: BlogPostFilterInput) {
  posts(first: 5, where: $where) {
    totalCount
    nodes { title status }
  }
}

query Search($where: BlogPostFilterInput) {
  posts(first: 10, where: $where) {
    totalCount
    nodes { title }
  }
}

query Sorted($order: [BlogPostSortInput!]) {
  posts(first: 3, order: $order) {
    nodes { title createdAt }
  }
}

query Combined($first: Int, $where: BlogPostFilterInput, $order: [BlogPostSortInput!]) {
  posts(first: $first, where: $where, order: $order) {
    totalCount
    nodes { title status createdAt }
  }
}

query AuthorsByName($where: AuthorFilterInput) {
  authors(first: 5, where: $where) {
    totalCount
    nodes { id name bio }
  }
}

query Nested {
  posts(first: 3) {
    nodes {
      title
      author { name }
      tags(first: 5) { nodes { name } }
      comments(first: 1) { totalCount }
    }
  }
}

query Deep {
  authors(first: 2) {
    nodes {
      name
      posts(first: 2) {
        nodes {
          title
          comments(first: 2) {
            nodes { text author { name } }
          }
        }
      }
    }
  }
}

query Projection {
  posts(first: 2) {
    nodes { title }
  }
}

query GetIds {
  authors(first: 1) { nodes { id name } }
  posts(first: 1) { nodes { id title } }
  tags(first: 1) { nodes { id name } }
}

query Node($id: ID!) {
  node(id: $id) {
    id
    ... on BlogPost {
      title
      slug
      author { name }
      tags(first: 5) { nodes { name } }
    }
  }
}

query Nodes($ids: [ID!]!) {
  nodes(ids: $ids) {
    id
    ... on BlogPost { title }
    ... on Author { name }
    ... on Tag { name }
  }
}

query WrongFragment($id: ID!) {
  node(id: $id) {
    id
    ... on Comment { text }
  }
}

query Legacy {
  postById(id: 1) { id title }
}

mutation CreateAuthor($input: CreateAuthorInput!) {
  createAuthor(input: $input) {
    author { id name bio }
  }
}

mutation CreatePost($input: CreatePostInput!) {
  createPost(input: $input) {
    blogPost { id title slug status }
    errors {
      __typename
      ... on SlugAlreadyInUseError { message slug }
      ... on AuthorNotFoundError { message authorId }
    }
  }
}

mutation UpdatePost($input: UpdatePostInput!) {
  updatePost(input: $input) {
    blogPost { id title slug status }
    errors {
      __typename
      ... on PostNotFoundError { message }
      ... on SlugAlreadyInUseError { message }
    }
  }
}

mutation DeletePost($input: DeletePostInput!) {
  deletePost(input: $input) {
    blogPost { id title }
    errors { __typename ... on PostNotFoundError { message } }
  }
}

mutation AddComment($input: AddCommentInput!) {
  addComment(input: $input) {
    comment { id text createdAt author { name } }
    errors {
      __typename
      ... on PostNotFoundError { message }
      ... on AuthorNotFoundError { message }
    }
  }
}

mutation CreateTag($input: CreateTagInput!) {
  createTag(input: $input) {
    tag { id name }
    errors { __typename ... on SlugAlreadyInUseError { message } }
  }
}

mutation DeleteTag($input: DeleteTagInput!) {
  deleteTag(input: $input) {
    tag { id name }
    errors { __typename ... on TagNotFoundError { message } }
  }
}

query NoFirst {
  posts { nodes { id } }
}

query Bad {
  posts(first: 1) { nodes { nope } }
}

query CostReport {
  posts(first: 10) {
    nodes {
      title
      author { name }
      comments(first: 10) { totalCount nodes { text author { name } } }
    }
  }
}

request.description:
Open this as a Postman 'WebSocket' request (not HTTP), connect, then send graphql-transport-ws frames.

1) Init:
{"type":"connection_init","payload":{}}

2) Wait for {"type":"connection_ack"}, then subscribe:
{"id":"1","type":"subscribe","payload":{"query":"subscription { onPostPublished { id title slug status author { name } } }"}}

3) In another tab, run '6. Mutations > Create post' with status PUBLISHED. The event arrives as {"id":"1","type":"next","payload":{...}}.

Per-post comments (dynamic topic):
{"id":"2","type":"subscribe","payload":{"query":"subscription($postId: Int!) { onCommentAdded(postId: $postId) { id text author { name } } }","variables":{"postId": 1}}}
